(window.TNQ=window.TNQ||[]).push({"terms":{"공경비":{"d":"국가나 지방자치단체가 경찰 같은 공적 기관을 통해 법 집행 권한으로 하는 경비입니다.","r":["민간경비","자체경비"]},"민간경비":{"d":"민간인이나 민간 업체가 고객과의 계약에 따라 인력과 장비로 안전을 지키는 경비입니다.","r":["공경비","계약경비"]},"자체경비":{"d":"기업이나 기관이 경비원을 직접 고용해 스스로 운영하는 경비 방식입니다.","r":["계약경비"]},"계약경비":{"d":"경비 전문 업체와 계약해 경비 업무를 맡기는 방식입니다.","r":["자체경비"]},"사인":{"d":"공적 권한이 없는 일반 개인을 가리키는 법률 용어입니다.","r":["증거능력"]},"위법성이 조각":{"d":"겉으로 법을 어긴 것처럼 보여도 정당한 사유가 있어 위법하지 않다고 보는 것입니다.","r":["정당방위","긴급피난"]},"정당방위":{"d":"부당한 침해에서 자신이나 타인의 권리를 지키려고 어쩔 수 없이 한 방어 행위입니다.","r":["긴급피난"]},"긴급피난":{"d":"닥친 위난을 피하려고 부득이 다른 사람의 법익을 해치는 행위입니다.","r":["정당방위"]},"증거능력":{"d":"어떤 자료를 재판에서 증거로 쓸 수 있는 법적 자격입니다.","r":[]},"경비지도사":{"d":"경비원을 지도하고 감독하는 업무를 맡는 경비 분야 국가자격 소지자입니다.","r":[]},"통솔범위":{"d":"한 명의 상관이 효과적으로 감독할 수 있는 부하의 수입니다.","r":[]},"재량권":{"d":"정해진 범위 안에서 스스로 판단해 처리할 수 있도록 부여된 권한입니다.","r":[]},"경비위해요소":{"d":"경비 대상을 위협하는 자연적, 인위적, 특정한 요인을 통틀어 이르는 말입니다.","r":[]},"비용효과분석":{"d":"투입한 비용과 얻는 효과를 견주어 적절한 경비 수준을 정하는 방법입니다.","r":[]},"콘서티나":{"d":"철조망의 한 종류로, 코일 모양이라 설치와 철거가 쉬워 이동성이 뛰어납니다.","r":[]},"기계경비":{"d":"센서, 경보기 같은 장비로 침입을 탐지하고 대응하는 경비 방식입니다.","r":["오경보"]},"오경보":{"d":"실제 침입이나 사고가 없는데 경보장치가 울리는 현상입니다.","r":["기계경비"]},"혼잡경비":{"d":"행사에 모인 군중으로 인한 혼란을 예방하고 사태 확대를 막는 경비 업무입니다.","r":[]},"레이블링":{"d":"자료나 파일에 보안 수준을 나타내는 표시를 붙여 그에 맞게 관리하는 방법입니다.","r":[]},"융합보안":{"d":"물리보안과 정보보안을 통합해 관리하고 효율을 높이는 활동입니다.","r":["통합인증제"]},"통합인증제":{"d":"한 번의 인증으로 여러 시스템을 이용하게 하는 방식으로 싱글 사인온이라고도 합니다.","r":["융합보안"]}},"notes":{"1980년대 이후 기계경비시스템이 점차적으로 도입되었다.":"1980년대부터 사람 대신 장비로 감시하는 기계경비시스템이 한국에 조금씩 들어왔어요.","1980년대 초 한국에 진출하였고 그 후반에는 중국에까지 진출하였다.":"일본 경비업체는 1980년대 초 한국에 먼저 들어왔고 후반에는 중국에까지 영업 범위를 넓혔습니다.","6개 경비업무 영역에 걸쳐 자격증제도를 운영하고 있다.":"일본은 여섯 가지 경비업무 영역마다 자격증제도를 운영하고 있다는 내용이에요.","각종 행사를 위해 모인 불특정 군중에 의해 발생되는 혼란 상태를 사전에 예방ㆍ경계하고, 위험한 사태가 발생한 경우에 신속하게 조치해 확대를 방지하는 경 비활동이다.":"혼잡경비는 행사에 모인 불특정 군중이 일으킬 혼란을 미리 막고 사고 시 확대를 막는 활동이에요.","개개인이 보유한 잠재능력을 개발ㆍ육성하고, 직장생활 능력 및 사회적 능력을 향상시키는 전인교육을 지향해야 한다.":"개인 측면의 교육훈련은 잠재능력을 키워 직장과 사회에서 쓸 능력을 높이는 전인교육을 목표로 해야 합니다.","개인, 기업, 정부단체 등의 데이터를 통합해 정확한 사고징후를 감지하고 총체적으로 대응할 수 있다.":"여러 주체의 데이터를 합치면 사고 징후를 더 정확히 포착하고 전체적으로 대응할 수 있어요.","건물에는 정교하면서도 파손되기 어려운 잠금장치를 설치해야 한다.":"건물에는 쉽게 부서지지 않는 정교한 잠금장치를 달아야 침입을 막을 수 있습니다.","경계구역의 안과 밖을 비출 수 있도록 적당한 밝기와 높이에 설치한다.":"보안조명은 경계구역 안팎을 모두 비추도록 알맞은 밝기와 높이로 달아요.","경비계획 과정에는 관련 분야나 계층의 충분한 참여가 이루어져야 한다.":"경비계획을 세울 때 관련 분야와 계층이 충분히 의견을 낼 수 있게 참여시켜야 해요.","경비 대상이 공경비와 구별된다.":"공경비는 국민 전반이 대상이지만 민간경비는 계약한 고객이나 시설이 대상입니다.","경비업계와 경찰 간의 상호 연대를 강화하는 추세이다.":"일본에서는 경비업계와 경찰이 서로 협력하는 관계를 더 단단히 하는 흐름이 이어집니다.","경비업법 제정 당시에는 신고제로 운영되었다가 허가제로 변경되었다.":"일본은 경비업법을 만들 때 신고만 하면 되던 신고제였다가 나중에 허가를 받는 허가제로 바뀌었죠.","경비업체들이 활동할 수 있는 업종이 일본에 비해 제한되어 있다.":"한국 경비업체가 할 수 있는 업종의 범위가 일본보다 좁게 정해져 있어요.","경비원은 자신을 직접 관리하고 있는 경비책임자로부터 지시를 받아야 하고, 항상 그 책임자에게 보고해야 한다.":"경비원은 자신을 직접 관리하는 책임자에게만 지시받고 보고하는 명령 계통을 지켜야 해요.","경비의 비용효과분석이란 투입비용에 대한 산출효과를 비교하여 적절한 경비수준을 결정하는 과정이다.":"비용효과분석은 들인 비용과 얻는 효과를 견주어 알맞은 경비 수준을 정하는 절차입니다.","경비의 주체를 공적 주체와 사적 주체로 명확하게 구분한다.":"경비를 하는 주체가 국가인지 개인이나 사기업인지로 공경비와 민간경비를 가르는 관점이죠.","경비조명은 침입자의 침입의도를 사전에 포기하도록 하는 심리적 압박과 건물의 미적 감각을 살려주는 역할을 한다.":"경비조명은 침입자가 마음먹기 전에 단념하게 압박을 주고 건물의 미관도 살려 줍니다.","경비협회의 업무는 경비업법에 규정되어 있다.":"경비협회가 하는 업무의 범위는 경비업법의 조문으로 정해 두고 있어요.","경비 활동의 전제가 된다. 경비위해요소를 인지하는 것은 경비대상시설이 안고 있는 경비상의 취약점을 파악하는 것이다.":"위해요소를 안다는 것은 경비 대상 시설이 지닌 경비상의 약한 곳을 찾아낸다는 뜻이에요.","경영전략의 전개에 필요한 인력의 확보, 기업문화의 전승을 위해 서 실시되는 것이다.":"기업은 전략 수행에 필요한 인력을 확보하고 기업문화를 이어 가려고 교육훈련을 합니다.","경찰과 민간경비는 상호보완적 관계에 있다.":"경찰이 다 채우지 못하는 치안 수요를 민간경비가 메우며 서로 부족한 점을 보완하는 관계입니다.","경찰관서에 직접 연결하는 기계경비 시스템에 대해 경찰이 거부감을 가질 수 있다.":"경찰서에 바로 연결하는 방식을 경찰 쪽에서 달가워하지 않을 수 있다는 단점입니다.","경찰의 민생 치안부서에 대한 기피 현상이 있다.":"주민 생활과 가까운 민생 치안부서에서는 경찰이 근무하기를 꺼리는 경향이 나타납니다.","계약경비보다 결원의 보충 및 추가인력의 배치가 상대적으로 어렵다.":"자체경비는 빠진 인원을 채우거나 인력을 더 투입하려면 직접 채용해야 해서 계약경비보다 번거롭죠.","계약경비보다 자신을 고용한 회사나":"회사가 직접 고용한 자체경비원은 소속 회사에 대한 충성도가 계약경비원보다 높다는 비교예요.","계층의 수가 적으면 통솔범위가 넓어지는 경향이 있다.":"계층이 적으면 상관과 부하 사이 단계가 줄어 한 상관이 더 많은 부하를 맡게 됩니다.","고대 로마 시대에는 지배자가 통치하는 군대가 운영되었으며, 이들은 최초의 비무장 수도경찰로 간주된다.":"지배자의 군대가 있었고, 그 군대가 최초의 비무장 수도경찰로 여겨진다는 내용이에요.","고용주에 대한 충성도가 상대적으로 높다.":"고용 관계가 직접 이어져 있어서 고용주를 향한 충성도가 계약경비보다 높은 편입니다.","권한 없는 사람이 해독할 수 없도록 관리한다.":"패스워드는 권한 없는 사람이 알아낼 수 없도록 관리해야 합니다.","극비의 자료가 수록된 파일이나 중요 프로그램이 수록된 파일에는 레이블링 (Labeling)에 의해 관리한다.":"레이블링은 극비 자료나 중요 프로그램 파일에 보안 수준 표시를 붙여 관리하는 방법이에요.","기계경비보다 인력경비에 치중되어 있는 현실이다.":"장비를 쓰는 기계경비보다 사람을 투입하는 인력경비 위주로 시장이 움직이고 있다는 말이에요.","긴급목적을 위해 만들어진 출입문은 외부의 침입으로부터 열리지 않도록 특별한 장치를 갖추고 있어야 한다.":"비상용 출입문은 밖에서 열고 들어올 수 없도록 특별한 잠금 장치를 갖추어야 합니다.","내국인의 해외범죄, 외국인의 국내범죄가 증가하고 있다.":"사람의 국경 이동이 늘면서 한국인이 해외에서, 외국인이 국내에서 저지르는 범죄가 늘고 있어요.","너무 맹신하면 범죄자에게 역이용 당할 가능성이 있다.":"기계만 믿으면 범죄자가 그 허점을 알아내 오히려 이용할 가능성이 생깁니다.","노인범죄 및 노인대상범죄가 증가하고 있다.":"인구가 늙어 가면서 노인이 저지르는 범죄와 노인을 노린 범죄가 함께 늘고 있습니다.","대다수 주에서 민간경비 서비스에 대한 자격증제도를 두고 있으며 점차 증가 추세에 있다.":"미국은 대부분의 주가 민간경비 서비스에 자격증제도를 두며 그 수가 계속 늘고 있어요.","대피 시에는 수건 등을 물에 적셔서 입과 코를 막고 낮은 자세로 대피한다.":"화재 때는 젖은 수건으로 입과 코를 막고 연기를 피해 낮은 자세로 대피하는 거예요.","마약범죄 증가가 사회문제로 대두되었다.":"청소년이 연루된 마약범죄가 늘어 사회문제로 떠올랐다는 내용이에요.","모든 층을 누르고 가장 먼저 정지하는 층에 내려서 대피한다.":"엘리베이터 안에서 지진을 만나면 모든 층 버튼을 눌러 가장 먼저 멈춘 층에서 내립니다.","물리보안시스템의 IT화에 따른 원가절감이 요구됨에 따라 중요성이 부각되고 있다.":"물리보안시스템이 IT화되면서 원가를 줄여야 한다는 요구가 생겨 융합보안이 주목받고 있습니다.","물리보안요소와 정보보안요소를 통합해 효율성을 높이는 활동이다.":"융합보안은 물리보안과 정보보안을 하나로 묶어 효율을 높이려는 활동이에요.","물리적 보안영역, 관리적 보안영역, 기술적 보안영역을 통합적으로 관리한다.":"물리적, 관리적, 기술적 세 보안영역을 따로 두지 않고 한꺼번에 관리합니다.","물리적 보안인증과 사이버 보안인증을 통합적으로 관리하여 보안관리를 강화한다.":"물리적 보안인증과 사이버 보안인증을 함께 관리해서 보안 수준을 끌어올립니다.","물리적 환경을 개선하여 범죄를 억제하고 주민의 불안감을 해소하고자 하는 이론이다.":"범죄가 일어나기 어렵게 물리적 환경을 바꾸고 주민의 불안을 줄이려는 이론이에요.","민간경비는 국가의 지도ㆍ감독 하에 제한적인 기능만을 담당한다.":"대륙법계에서는 민간경비가 국가의 감독을 받으며 맡을 수 있는 기능도 한정됩니다.","민간경비원의 교육과정이 현실과 맞지 않는다는 지적이 있다.":"민간경비원이 받는 교육의 내용이 실제 현장 업무와 어긋난다는 비판이 있습니다.","민간경비원의 법적 지위를 크게 3가지 유형으로 구분하였다.":"비렉은 민간경비원이 법적으로 어떤 자격으로 활동하는지를 세 유형으로 나누었어요.","민간경비의 업무범위가 경찰과 유사하나 집행 권한에 차이가 있다.":"영미법계에서는 민간경비가 경찰과 하는 일은 비슷해도 집행 권한이 서로 다릅니다.","발생 시 가스밸브를 잠그고 건물 밖 공터 등으로 대피한다.":"지진이 나면 가스밸브를 잠가 가스 사고를 막고 건물 밖 공터로 대피합니다.","범죄에 대한 수사권을 행사할 수 없다.":"수사는 경찰 같은 수사기관의 권한이어서 민간경비원은 범죄 수사를 할 수 없습니다.","법적 지위는 일반시민과 같은 사인(私人)에 불과하다.":"민간경비원은 경찰 같은 공적 권한이 없고 일반 시민과 똑같은 사인의 지위에 있습니다.","부하가 조직적이고, 책임감 있게 일할 수 있다.":"명령 계통이 분명하면 부하가 질서 있게 움직이고 책임감을 가지고 일할 수 있어요.","상급자의 통솔범위는 부하의 자질이 높을수록 넓다.":"부하의 자질이 높으면 스스로 일을 처리해 감독 부담이 줄어서 통솔범위가 넓어집니다.","상품판매시설의 경우 직원용 출입구와 고객용 출입구를 구분하는 것이 좋다.":"매장에서는 직원 출입구와 고객 출입구를 따로 두어 사람의 흐름을 분리하는 편이 좋아요.","상황에 따라 필요시 보호 우선순위에 의한 안전을 확보한다.":"상황에 따라 보호해야 할 사람의 우선순위를 정해 그 순서대로 안전을 지킵니다.","소방기관과의 연락방법에 대한 지도는 경비지도사의 직무이다.":"소방기관과 어떻게 연락하는지 지도하는 일은 경비지도사가 맡는 직무에 속합니다.","수집한 증거가 법정에서 원용될 경우 증거능력이 인정된다.":"민간경비원이 모은 증거도 재판에서 쓰이면 법정에서 증거로 인정될 자격이 있어요.","시설경비ㆍ공항보안 뿐 아니라 핵연료물질 운반 등 폭 넓은 분야로 발전하였다.":"일본 민간경비는 시설경비와 공항보안에서 핵연료물질 운반 같은 분야까지 업무가 넓어졌어요.","업무의 책임소재를 분명하게 할 수 있다.":"지시와 보고가 한 줄로 이어지면 누가 어떤 업무를 책임지는지 가리기 쉬워집니다.","업무흐름과 프로그램의 내용이 불일치하지 않도록 문서기록화를 철저히 한다.":"업무 흐름과 프로그램 내용이 어긋나지 않도록 문서로 빠짐없이 기록해 두어야 해요.","여러 장소에 근무하는 경비원을 통솔하는 것보다 한 곳에 근무하는 경비원을 통솔하는 것이 통솔범위가 넓다.":"근무지가 한 곳에 모여 있으면 감독하기 쉬워 통솔범위가 넓어지고, 흩어지면 좁아집니다.","여러 종류의 차량 통행이 이루어지기 때문에 충분히 넓어야 한다.":"여러 종류의 차량이 오가므로 차량출입구는 넉넉히 넓게 만들어야 합니다.","영역이 뚜렷하고 확실하게 구분되는 것은 아니다.":"두 영역은 겹치는 부분이 있어서 업무 범위를 칼로 자르듯 나눌 수는 없습니다.","오경보의 문제가 있을 수 있다.":"오경보는 실제 침입이 아닌데 경보가 울리는 것으로 기계경비의 대표적인 약점입니다.","외국인 근로자 및 불법체류자 등에 의한 범죄 가 증가하고 있다.":"외국인 근로자와 불법체류자가 저지르는 범죄가 늘고 있다는 이야기예요.","외부 침입을 정확하게 탐지하고 신속하게 대응할 수 있다.":"기계장치가 침입을 정확히 알아내 사람이 빨리 대응하도록 도와줍니다.","용역경비업법이 경비업법으로 변경됨으로써 포괄적인 개념의 전문경비제도를 도입하는 계기가 되었다.":"용역경비업법이 경비업법으로 바뀌면서 경비 업무 전반을 아우르는 전문경비제도가 도입되는 계기가 되었습니다.","운반 중에 있는 현금ㆍ유가증권ㆍ귀금속ㆍ상품 그 밖의 물건에 대하여 도난ㆍ화재 등 위험발생을 방지하는 업무를 의미한다.":"호송경비는 옮기는 중인 현금과 귀금속 같은 물건을 도난이나 화재에서 지키는 업무예요.","울타리, 도로상의 방책, 초소ㆍ망루 등":"인공적 장벽은 사람이 만든 울타리, 도로 방책, 초소와 망루 같은 시설을 말해요.","원시시대의 대표적인 경비 형태는 절벽 동굴이나 수상가옥 등 주거지를 이용한 방법 이다.":"원시시대에는 절벽 동굴이나 물 위의 집 같은 주거지 자체가 외부 위협을 막는 경비였어요.","유지보수에 전문 인력이 요구된다.":"장비를 점검하고 고치는 일에는 기술을 갖춘 전문 인력이 있어야 합니다.","인파가 무질서한 경우가 많으므로 적절한 안내와 통솔을 통하여 질서를 도모한다.":"피난하는 인파는 무질서한 경우가 많아서 안내와 통솔로 질서를 잡아야 해요.","일반 국민들을 위하여 관할 구역 내에서 법 집행의 권한을 가진다.":"국가기관인 경찰이 하는 경비이고, 법을 집행할 권한이 있다는 점이 민간경비와 다릅니다.","일본은 경비업법 제2조 2호 업무에 혼잡경비를 규정하고 있다.":"일본은 경비업법 제2조 2호에서 혼잡경비를 하나의 경비업무로 정해 두고 있어요.","일부 주에서는 경찰관 신분으로 민간경비회사에서 part-time job을 하기도 한다.":"미국 일부 주에서는 현직 경찰관이 겸직으로 민간경비회사에서 시간제로 일하기도 합니다.","일선 치안현장의 경찰인력이 부족하다.":"현장 치안을 맡는 일선 경찰의 인원이 필요한 만큼 채워지지 않은 상태입니다.","임용된 사람은 2주간 76시간의 교육":"청원경찰로 임용된 사람이 받는 신임교육은 2주 동안 76시간이라는 기준이에요.","자연현상에 의해 야기되는 자연재해이다.":"자연적 위해는 사람이 아닌 자연현상이 원인이 되어 생기는 재해를 말해요.","자체경비보다 상대적으로 전문성이 높다.":"계약경비는 경비를 전문으로 하는 업체가 맡기 때문에 자체경비보다 전문성이 높은 편이에요.","장기적으로 경비 소요비용의 절감효과를 가져온다.":"초기 설비에는 돈이 들지만 오래 쓰면 사람에게 드는 비용이 줄어 경비 전체 비용이 낮아집니다.","장기적으로 운영비용의 절감효과를 기대할 수 있다.":"시스템이 자리를 잡은 뒤에는 운영하는 데 드는 돈이 줄어들 것으로 기대할 수 있죠.","정당방위나 긴급피난은 위법성이 조각된다.":"정당방위나 긴급피난에 해당하면 그 행위는 법에 어긋나는 행위로 보지 않아요.","정보시스템의 보안은 주기적으로 재평가되어야 한다.":"정보시스템 보안은 한 번 만들고 끝내지 않고 일정한 주기로 다시 평가해야 합니다.","정보시스템의 보안은 타인의 권리와 합법적 이익이 존중될 수 있도록 운영되어야 한다.":"정보시스템을 운영할 때 다른 사람의 권리와 정당한 이익을 해치지 않아야 해요.","정보와 정보시스템의 사용을 허가 받은 사람이 이를 사용하려고 할 때는 언제든지 이를 사용할 수 있도록 보장하는 것을 의미한다.":"가용성은 사용이 허가된 사람이 원할 때 언제든 정보와 시스템을 쓸 수 있게 보장하는 성질이에요.","제2차 세계대전 이후에 현대적 민간경비업의 출현을 맞이하게 되었다.":"일본에서는 제2차 세계대전 후에야 오늘날과 같은 모습의 민간경비업이 나타났어요.","제한된 근무지역 내에서 경찰권을 일부 행사할 수 있는 민간경비원도 있다.":"근무지역이 정해진 범위 안에서만 경찰권 일부를 행사하는 민간경비원도 있다는 말이에요.","조명시설의 위치가 경비원의 시야를 방해해서는 안 되며, 가능한 그림자가 생기지 않도록 설치해야 한다.":"조명이 경비원의 시야를 가리거나 그림자를 만들면 감시에 방해되므로 위치를 신중히 잡습니다.","조직의 장으로 하여금 전체적인 조정을 가능하게 한다.":"명령이 한 계통으로 모이면 조직의 장이 전체를 아우르며 조정하는 것이 가능해집니다.","직무수행에 필요한 지식과 기술 습득, 일반능력 개발, 가치관의 발전적 변화를 촉진하 는 계획적 활동이다.":"교육훈련은 직무에 필요한 지식과 기술을 익히고 가치관까지 바람직하게 바꾸려는 계획된 활동이에요.","창문과 출입문 등과 같이 경계구역과 연결되어 있는 문은 튼튼한 구조물로 이루어져야 한다.":"경계구역과 맞닿은 창문과 출입문이 약하면 침입 통로가 되므로 튼튼하게 만들어야 합니다.","창문과 출입문은 화재나 여러 가지 위험한 사고의 발생에 대비하여 비상구 등 예비적 조치가 사전에 충분히 마련되어야 한다.":"화재나 사고가 날 때를 대비해 창문과 출입문에는 비상구 같은 예비 조치를 미리 마련해 둡니다.","첨단범죄의 증가로 이에 대응하는 민간경비의 전문성이 요 구될 것이다.":"첨단범죄가 늘어 그에 맞서는 민간경비에게도 전문성을 갖추라는 요구가 커질 전망입니다.","초고층 빌딩 등 특수한 경우를 제외하고 엘리베이터는 사용하지 않는다.":"초고층 빌딩 같은 특수한 경우가 아니면 피난할 때 엘리베이터를 타지 않습니다.","최고관리자는 중간관리자에게 책임의 범위 내에서 업무를 수행할 수 있도록 재량권을 부여하여야 한다.":"최고관리자가 중간관리자에게 책임 범위 안에서 스스로 판단해 일할 권한을 맡겨야 합니다.","최첨단 CCTV 등 과학치안의 필요성이 있다.":"CCTV 같은 첨단 장비로 범죄를 막는 과학치안이 필요하다는 뜻이에요.","출입문은 정문과 후문의 주 용도를 구분하는 것이 좋다.":"정문과 후문은 쓰임새를 나누어 두는 편이 관리하기 좋다는 권고예요.","콘서티나 철사는 철조망 설치 및 제거가 용이하여 이동성이 뛰어난 철조망이다.":"콘서티나 철사는 설치하고 걷어 내기 쉬워 옮겨 가며 쓰기에 알맞은 철조망이에요.","탈출 시 발생하는 혼란상황을 방지하기 위해 출입구와 비상구를 확실하게 장악하고 통제한다.":"출입구와 비상구를 경비원이 장악해 통제하면 탈출하는 사람들이 몰려 생기는 혼란을 줄일 수 있습니다.","통합인증제(Single Sign On)가 융합보안의 대표적 사례이다.":"통합인증제는 한 번 로그인하면 여러 시스템을 쓸 수 있게 하는 융합보안의 대표 사례예요.","특정 시설물 및 국가 등에 따라 성질이나 유형이 다양하게 나타나는 위해이다.":"특정한 위해는 시설물이나 국가마다 성질과 형태가 달라 일률적으로 정할 수 없는 위해예요.","피난자가 다수인 경우에는 사람들을 분산하여 혼란을 방지하고 위험장소에 있는 자가 조기에 피난할 수 있도록 한다.":"피난자가 많을 때는 사람들을 나누어 혼란을 막고 위험 장소에 있는 사람이 먼저 빠지게 합니다.","한국은 시설경비업무 등을 통하여 혼잡경비업무를 수행하고 있다.":"한국은 시설경비업무 같은 업무를 통해 혼잡경비를 해내고 있습니다.","한 사람의 상관이 효과적으로 감독할 수 있는 부하직원의 수":"통솔범위는 상관 한 명이 효과적으로 감독할 수 있는 부하 직원의 숫자를 가리킵니다.","함무라비 시대에는 정부가 법 집행을 할 수 있고 개인에게 책임을 부여할 수 있었다.":"함무라비 시대에는 정부가 법을 집행하고 개인에게 책임을 지우는 체제가 갖추어져 있었습니다.","해킹 등 첨단사이버범죄가 대폭 증가하고 있다.":"인터넷과 통신망이 발달하면서 해킹 같은 첨단 사이버범죄가 크게 늘었다는 뜻입니다.","현장보존의 범위에 있는 모든 사람을 신속히 퇴장시킨다.":"현장보존이 필요한 범위 안에 있던 사람은 빨리 밖으로 내보내야 해요.","홍수, 폭풍, 지진 등이 있다.":"자연적 위해의 예로는 홍수와 폭풍, 지진을 꼽습니다.","효과적인 경비프로그램을 실행하기 위해서는 경비위해요소 조사와 분석이 선행되어야 한다.":"경비프로그램은 위해요소 조사와 분석을 마친 뒤에야 효과 있게 실행할 수 있습니다."}});if(window.DIAGRAM&&DIAGRAM.tnFlush)DIAGRAM.tnFlush();
/*tnote-data-end*/
